依赖：`junit-jupiter`（含 `junit-jupiter-params`）、`jackson-databind`。

## FreightSamples.java

```java
package com.example.freight;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Iterator;
import java.util.List;
import java.util.stream.Stream;

/**
 * 样本目录的读写与规整。
 *
 * <p>规整规则（去掉每次都变的字段）必须和 record-replay 录制时用的是同一份，
 * 否则回放侧多出 traceId/calcTime，老类别会整片红，而那不是行为差异。
 */
final class FreightSamples {

    /** 相对仓库根目录；Maven / Gradle 跑测试时工作目录就是项目根。 */
    static final Path DIR = Path.of("samples", "freight");

    /** 每次都变的字段清单，录制与回放两侧共用。 */
    private static final List<String> VOLATILE_FIELDS = List.of("traceId", "calcTime");

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private FreightSamples() {}

    /** 所有样本场景名（文件名去掉 .request.json），排序后返回，保证跑批顺序稳定。 */
    static Stream<String> allScenarios() {
        try (var files = Files.list(DIR)) {
            return files.map(p -> p.getFileName().toString())
                    .filter(n -> n.endsWith(".request.json"))
                    .map(n -> n.substring(0, n.length() - ".request.json".length()))
                    .sorted()
                    .toList()
                    .stream();
        } catch (IOException e) {
            throw new UncheckedIOException("读不到样本目录 " + DIR.toAbsolutePath(), e);
        }
    }

    /** 老类别：有母版的场景。 */
    static Stream<String> scenariosWithApproved() {
        return allScenarios().filter(FreightSamples::hasApproved);
    }

    static boolean hasApproved(String scenario) {
        return Files.exists(approvedPath(scenario));
    }

    static Path requestPath(String scenario) {
        return DIR.resolve(scenario + ".request.json");
    }

    static Path approvedPath(String scenario) {
        return DIR.resolve(scenario + ".approved.json");
    }

    static FreightReq readRequest(String scenario) {
        try {
            return MAPPER.readValue(Files.readString(requestPath(scenario), StandardCharsets.UTF_8),
                    FreightReq.class);
        } catch (IOException e) {
            throw new UncheckedIOException("读不到请求样本 " + requestPath(scenario), e);
        }
    }

    /** 母版文本。只去掉文件末尾换行，其余一个字节都不动。 */
    static String readApproved(String scenario) {
        try {
            return stripTrailingNewline(Files.readString(approvedPath(scenario), StandardCharsets.UTF_8));
        } catch (IOException e) {
            throw new UncheckedIOException("读不到母版 " + approvedPath(scenario), e);
        }
    }

    /** 把实际输出序列化成和母版同一种形态：紧凑、字段按声明顺序、中文不转义、规整掉易变字段。 */
    static String canonical(Object response) {
        try {
            return MAPPER.writeValueAsString(canonicalTree(response));
        } catch (IOException e) {
            throw new UncheckedIOException("序列化实际输出失败", e);
        }
    }

    static JsonNode canonicalTree(Object response) {
        JsonNode tree = MAPPER.valueToTree(response);
        normalise(tree);
        return tree;
    }

    /** 递归去掉易变字段。 */
    private static void normalise(JsonNode node) {
        if (node.isObject()) {
            ObjectNode obj = (ObjectNode) node;
            obj.remove(VOLATILE_FIELDS);
            for (Iterator<JsonNode> it = obj.elements(); it.hasNext(); ) {
                normalise(it.next());
            }
        } else if (node.isArray()) {
            node.forEach(FreightSamples::normalise);
        }
    }

    private static String stripTrailingNewline(String s) {
        return s.endsWith("\n") ? s.substring(0, s.length() - 1).stripTrailing() : s;
    }
}
```

## OldPathUnchangedGoldenMasterTest.java（老类别）

```java
package com.example.freight;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

import java.util.stream.Stream;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * 老类别：改动之前就存在的请求。
 *
 * <p>证的是「老路径一点没变」。期望值来自改动前录下的 approved 文件，
 * 整段序列化结果逐字节相等，不挑字段比。
 *
 * <p>注意 首重续重-广东 这条：模板 1032 配了偏远省份表，广东不在表中，
 * 所以它其实走的是新代码路径，但输出必须和母版一模一样——这条是本组里最要紧的一条。
 */
@DisplayName("母版比对：老路径输出未变")
class OldPathUnchangedGoldenMasterTest {

    @ParameterizedTest(name = "{0}")
    @MethodSource("oldCategoryScenarios")
    void outputMatchesApprovedByteForByte(String scenario) {
        FreightReq req = FreightSamples.readRequest(scenario);

        String actual = FreightSamples.canonical(FreightCalc.calc(req));

        assertEquals(FreightSamples.readApproved(scenario), actual,
                () -> "老路径输出与母版不一致：" + scenario
                        + "（母版：" + FreightSamples.approvedPath(scenario) + "）");
    }

    static Stream<String> oldCategoryScenarios() {
        return FreightSamples.scenariosWithApproved();
    }
}
```

## RemoteSurchargeNewPathTest.java（新类别）

```java
package com.example.freight;

import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * 新类别：偏远附加按省份查表这条改动引入的请求。
 *
 * <p>证的是「新路径是对的」。期望值是需求例子里的独立字面值，
 * 写死在测试里，不从当前输出生成 approved 文件——那样只是代码和自己比。
 */
@DisplayName("新路径：偏远附加按省份查表")
class RemoteSurchargeNewPathTest {

    private static final String SCENARIO = "首重续重-新疆-vip";

    /** 需求例子：模板 1032、新疆、3.2kg、vip → 26。 */
    @Test
    @DisplayName("模板 1032（配了偏远省份表）+ 新疆 + 3.2kg + vip → 运费 26")
    void remoteProvinceSurchargeAppliesForListedProvince() {
        FreightReq req = FreightSamples.readRequest(SCENARIO);

        JsonNode actual = FreightSamples.canonicalTree(FreightCalc.calc(req));

        assertEquals(26, actual.path("fee").intValue(),
                () -> "新路径运费与需求例子不符，实际输出：" + actual);
    }
}
```

## SampleSetCoverageTest.java（防漏）

```java
package com.example.freight;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;

/** 每个 request 样本要么有母版（老类别），要么登记在新类别里，不允许有样本没人比。 */
class SampleSetCoverageTest {

    /** 新类别场景，对应 RemoteSurchargeNewPathTest 里的用例。加新样本时同步登记。 */
    private static final Set<String> NEW_CATEGORY = Set.of("首重续重-新疆-vip");

    @Test
    @DisplayName("样本集合：每条样本都归入老类别或新类别")
    void everySampleIsCovered() {
        List<String> uncovered = FreightSamples.allScenarios()
                .filter(s -> !FreightSamples.hasApproved(s) && !NEW_CATEGORY.contains(s))
                .toList();

        assertEquals(List.of(), uncovered, "这些样本既没有母版也没登记为新类别");
    }
}
```

## 需要你对齐的三处

1. 包名和 `FreightReq` / 响应类型名 —— 我按 `FreightCalc.calc(FreightReq)` 假设的，改成仓里真实签名。
2. 录制时的序列化器 —— 母版长这样 `{"fee":18,"items":[{"name":"首重","fee":10},...]}`：紧凑、无空格、字段按声明顺序、中文不转义。`FreightSamples.canonical` 是照这个配的。如果录制用的是别的 writer（比如带缩进），把两边统一成同一个再跑。
3. 规整字段清单 —— 我写死了 `traceId`、`calcTime`，按你录制时实际的清单补。

## 两条我看到的缺口（不改你的方案，只报）

- 老类别只有两条：2001/北京（模板没配表，纯老代码）和 1032/广东（配了表但省份不在表中，走新代码分支）。**缺「配了表 + 省份在表中 + 非 vip」**这一档——现在 vip 和偏远两个条件搅在一起，26 这个数字红了说不清是哪边错。
- 比对结果（命令 + 退出码）按步骤 5 要和母版、回放测试进同一个 PR。Bash 这边跑不了，你跑完把输出贴回来我按 `verify-evidence` 整理。

## 一个问题

新类别现在只断言了 `fee == 26`，`items` 没锁。比如老类别的母版是整段比的，能抓到 items 里少一行或名字写错；新类别只比一个数字，假如新路径算出 `[{"name":"首重","fee":10},{"name":"续重","fee":8},{"name":"偏远","fee":8}]` 和 `[{"name":"首重","fee":10},{"name":"偏远附加","fee":16}]`，两者 fee 都是 26，测试都绿。

需求例子里只给了 26，没给明细。**新疆这条的 items 应该是哪几行、各多少钱？** 你给了我就按字面值写全，顺手手写一个 `首重续重-新疆-vip.approved.json` 当它的母版；给不了的话就维持只锁 fee，我在测试注释里标明这个缺口。

按 `golden-master` 写好了。Bash 不可用，我没跑过任何东西 —— 下面是代码和布局，跑的命令和要贴的证据放在最后。

先说一件从你给的样本里看出来的事实（会影响测试怎么命名）：`首重续重-广东` 的 templateId 是 **1032**，而 1032 正是配了偏远省份表的模板。所以这条老类别样本走的是**新代码路径**，只是广东不在表里、输出必须一字不差 —— 它是三条里最值钱的一条。`首重-北京-cod`（2001，没配表）完全不碰新代码，是对照组。两条刚好盖住老路径的两个分支。

## 文件布局

```
repo-root/
├─ samples/freight/                                  ← record-replay 录的，位置不动
│  ├─ 首重续重-广东.request.json
│  ├─ 首重续重-广东.approved.json                     ← 母版：改前的提交录的
│  ├─ 首重-北京-cod.request.json
│  ├─ 首重-北京-cod.approved.json                     ← 母版：改前的提交录的
│  └─ 首重续重-新疆-vip.request.json                  ← 新类别，故意没有 .approved.json
├─ src/test/java/com/example/freight/
│  ├─ FreightCalcGoldenMasterTest.java               ← 老类别：比母版，逐字节
