│  └─ support/SampleReplay.java                      ← 读样本 / 规整 / 规范化
└─ .gitattributes
```

`.gitattributes` 加一行，免得 Windows 检出成 CRLF 时母版文本对不上（规范化后是紧凑单行，其实已经吃掉了换行，这行是双保险）：

```gitattributes
samples/**/*.json text eol=lf
```

## `SampleReplay.java`

```java
package com.example.freight.support;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import java.util.stream.Stream;

/**
 * 样本回放的唯一出入口。只做三件事：读样本、剪掉每次都变的字段、把 JSON 变成规范化文本。
 *
 * VOLATILE_FIELDS 必须和 record-replay 录样本时用的规整名单一致。动这里等于动母版的含义，
 * 动之前先看一眼 approved 文件里到底还剩哪些字段。
 */
public final class SampleReplay {

    /** 样本目录。Maven 和 Gradle 跑测试时工作目录都是模块根。 */
    public static final Path SAMPLES = Path.of("samples", "freight");

    /** 录样本时已规整掉的字段。实际输出要按同一份名单剪，才谈得上逐字节比。 */
    private static final Set<String> VOLATILE_FIELDS = Set.of("traceId", "calcTime");

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private SampleReplay() {}

    public static Path request(String scenario) {
        return SAMPLES.resolve(scenario + ".request.json");
    }

    public static Path approved(String scenario) {
        return SAMPLES.resolve(scenario + ".approved.json");
    }

    /** 读一条请求，反序列化成入参对象。 */
    public static <T> T readRequest(String scenario, Class<T> type) {
        try {
            return MAPPER.readValue(Files.readString(request(scenario), StandardCharsets.UTF_8), type);
        } catch (IOException e) {
            throw new UncheckedIOException("读不到请求样本：" + request(scenario), e);
        }
    }

    /** 实际输出 → 序列化 → 剪掉易变字段 → 规范化文本。回放比对里的「实际」就是这个。 */
    public static String replay(Object result) {
        try {
            return canonical(MAPPER.valueToTree(result));
        } catch (RuntimeException e) {
            throw new IllegalStateException("序列化实际输出失败：" + result, e);
        }
    }

    /** 回放结果的树形式，给只能比单个字段的新类别用。 */
    public static JsonNode replayTree(Object result) {
        try {
            return MAPPER.readTree(replay(result));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** 读母版，走同一套规范化，排掉缩进、字段顺序这类不算行为的差异。 */
    public static String readApproved(String scenario) {
        try {
            return canonical(Files.readString(approved(scenario), StandardCharsets.UTF_8));
        } catch (IOException e) {
            throw new UncheckedIOException("读不到母版：" + approved(scenario), e);
        }
    }

    /** 把一段 JSON 字面值变成规范化文本，供新类别写期望值。 */
    public static String canonical(String json) {
        try {
            return canonical(MAPPER.readTree(json));
        } catch (IOException e) {
            throw new UncheckedIOException("这段 JSON 解析不了：" + json, e);
        }
    }

    /** 样本目录里现有的场景名，排序后返回。 */
    public static List<String> scenarios() {
        try (Stream<Path> files = Files.list(SAMPLES)) {
            return files.map(p -> p.getFileName().toString())
                    .filter(n -> n.endsWith(".request.json"))
                    .map(n -> n.substring(0, n.length() - ".request.json".length()))
                    .sorted()
                    .toList();
        } catch (IOException e) {
            throw new UncheckedIOException("列不了样本目录：" + SAMPLES.toAbsolutePath(), e);
        }
    }

    private static String canonical(JsonNode node) {
        try {
            return MAPPER.writeValueAsString(canonicalise(node));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * 对象字段名排序 + 剪掉易变字段；数组顺序原样保留（items 的顺序是行为，不是格式）。
     * 两边都过这一道，所以排序不会盖住真的差异，只会盖住排版差异。
     */
    private static JsonNode canonicalise(JsonNode node) {
        if (node.isObject()) {
            ObjectNode sorted = MAPPER.createObjectNode();
            for (String name : new TreeSet<>(fieldNames(node))) {
                if (!VOLATILE_FIELDS.contains(name)) {
                    sorted.set(name, canonicalise(node.get(name)));
                }
            }
            return sorted;
        }
        if (node.isArray()) {
            ArrayNode kept = MAPPER.createArrayNode();
            node.forEach(child -> kept.add(canonicalise(child)));
            return kept;
        }
        return node;
    }

    private static List<String> fieldNames(JsonNode node) {
        List<String> names = new ArrayList<>();
        node.fieldNames().forEachRemaining(names::add);
        return names;
    }
}
```

## `FreightCalcGoldenMasterTest.java` —— 老类别

```java
package com.example.freight;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

import java.nio.file.Files;
import java.util.List;
import java.util.stream.Stream;

import static com.example.freight.support.SampleReplay.*;
import static org.junit.jupiter.api.Assertions.*;

/**
 * 老类别：改动之前就存在的请求。证的是「老路径一点没变」。
 *
 * 期望值是改动前的提交上录的 approved 文件（record-replay），不是改后跑出来的输出——
 * 拿改后输出当母版，比的是代码和自己，永远通过。
 *
 * 两条样本盖住老路径的两个分支：
 *   首重续重-广东   模板 1032 配了偏远省份表、广东不在表中 → 走新代码，输出必须一字不差
 *   首重-北京-cod   模板 2001 没配表 → 完全不碰新代码，对照组
 */
class FreightCalcGoldenMasterTest {

    private static final List<String> OLD_CATEGORY = List.of("首重续重-广东", "首重-北京-cod");
    private static final String NEW_CATEGORY = "首重续重-新疆-vip";

