                scenarios(),
                "样本目录和测试名单脱节了：新增样本要先归类，是比母版还是比需求例子");

        OLD_CATEGORY.forEach(scenario ->
                assertTrue(Files.exists(approved(scenario)),
                        () -> "老类别缺母版：" + approved(scenario)));

        assertFalse(Files.exists(approved(NEW_CATEGORY)),
                "新类别不许有 approved 文件：它的期望值来自需求翻译的例子，"
                        + "从当前输出生成母版等于把 bug 一起认可了");
