package com.example.freight.golden;

import com.fasterxml.jackson.core.util.DefaultIndenter;
import com.fasterxml.jackson.core.util.DefaultPrettyPrinter;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.ObjectWriter;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/** 母版的读取、规整与规范文本。规整规则只在这里定义一份。 */
final class GoldenMaster {

    static final String REQUEST_SUFFIX = ".request.json";
    static final String APPROVED_SUFFIX = ".approved.json";

    /**
     * 录制时规整掉的字段：每次都变，不是行为差异。
     * 录制侧改了规整规则，这里必须同步改，否则老类别会红在格式上。
     */
    private static final Set<String> VOLATILE_FIELDS = Set.of("traceId", "calcTime");

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private static final ObjectWriter WRITER = MAPPER.writer(
            new DefaultPrettyPrinter()
                    .withObjectIndenter(new DefaultIndenter("  ", "\n"))
                    .withArrayIndenter(new DefaultIndenter("  ", "\n")));

    private GoldenMaster() {
    }

    /** 样本目录。多模块或 IDE 改了工作目录时用 -Dsamples.dir 指。 */
    static Path samplesDir() {
        String override = System.getProperty("samples.dir");
        if (override != null) {
            return Paths.get(override);
        }
        for (Path p = Paths.get("").toAbsolutePath(); p != null; p = p.getParent()) {
            Path candidate = p.resolve("samples").resolve("freight");
            if (Files.isDirectory(candidate)) {
                return candidate;
            }
        }
        throw new IllegalStateException("找不到 samples/freight，用 -Dsamples.dir 指定目录");
    }

    static JsonNode requestNode(String scenario) {
        return read(samplesDir().resolve(scenario + REQUEST_SUFFIX));
    }

    /** 母版文本。文件里的缩进、键序差异不算差异；值、键集合、数组顺序都算。 */
    static String approvedText(String scenario) {
        return canonicalText(read(samplesDir().resolve(scenario + APPROVED_SUFFIX)));
    }

    /** 整份文档的规范文本，逐字节比的就是它，不挑字段。 */
    static String canonicalText(JsonNode node) {
        try {
            return WRITER.writeValueAsString(canonical(node)) + "\n";
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** 给新类别用：把手写的期望值字面值变成同一套规范文本。 */
    static String canonicalTextOf(String json) {
        try {
            return canonicalText(MAPPER.readTree(json));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** 目录里有哪些场景（按后缀分）。 */
    static List<String> scenarios(String suffix) {
        try (Stream<Path> files = Files.list(samplesDir())) {
            return files.map(p -> p.getFileName().toString())
                    .filter(n -> n.endsWith(suffix))
                    .map(n -> n.substring(0, n.length() - suffix.length()))
                    .sorted()
                    .collect(Collectors.toList());
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static JsonNode canonical(JsonNode node) {
        if (node.isObject()) {
            Map<String, JsonNode> sorted = new TreeMap<>();
            node.fields().forEachRemaining(e -> {
                if (!VOLATILE_FIELDS.contains(e.getKey())) {
                    sorted.put(e.getKey(), canonical(e.getValue()));
                }
            });
            ObjectNode out = MAPPER.createObjectNode();
            sorted.forEach(out::set);
            return out;
        }
        if (node.isArray()) {
            // items 的顺序是行为的一部分，不排序
            ArrayNode out = MAPPER.createArrayNode();
            node.forEach(child -> out.add(canonical(child)));
            return out;
        }
        return node;
    }

    private static JsonNode read(Path path) {
        try {
            return MAPPER.readTree(Files.readString(path, StandardCharsets.UTF_8));
        } catch (IOException e) {
            throw new UncheckedIOException("读不到样本 " + path, e);
        }
    }
}
```

