import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 老路径一点没变：回放改动前录的请求，与改动前录的母版逐字节相等。
 *
 * 首重续重-广东 走的是模板 1032——改后这个模板配了偏远省份表，但广东不在表里，
 * 所以这一条同时是「配了表也不碰表外省份」的证据。
 */
class FreightOldPathUnchangedTest {

    /** 改动引入的新类别：不该有母版，期望值在 FreightRemoteSurchargeTest。 */
    static final List<String> NEW_CATEGORIES = List.of("首重续重-新疆-vip");

    static Stream<String> oldCategories() {
        return GoldenMaster.scenarios(GoldenMaster.APPROVED_SUFFIX).stream();
    }

    @ParameterizedTest(name = "[{0}] 与改动前的母版逐字节相等")
    @MethodSource("oldCategories")
    void 老类别回放后与母版相等(String scenario) {
        assertFalse(NEW_CATEGORIES.contains(scenario), () ->
                "新类别 " + scenario + " 出现了 approved 文件。母版只能录自改动之前；"
                        + "拿改后的输出当母版，比的是代码和它自己，永远通过。");

        String expected = GoldenMaster.approvedText(scenario);
        String actual = GoldenMaster.canonicalText(
                FreightReplay.replay(GoldenMaster.requestNode(scenario)));

        assertEquals(expected, actual, () ->
                "回放与母版不一致：" + scenario + "\n"
                        + "红了先判三种之一：①每次都变的字段没规整（改 GoldenMaster.VOLATILE_FIELDS，"
                        + "并同步录制侧）②主人认可的预期改变（主人点头才更新 approved）③改坏了（回去修代码）。");
    }

    @Test
    void 每个请求样本都归入一类() {
        List<String> requests = GoldenMaster.scenarios(GoldenMaster.REQUEST_SUFFIX);
        assertFalse(requests.isEmpty(),
                "一个样本都没找到，先确认 samples/freight 的位置（-Dsamples.dir）");

        List<String> approved = GoldenMaster.scenarios(GoldenMaster.APPROVED_SUFFIX);
        List<String> orphans = requests.stream()
                .filter(s -> !approved.contains(s) && !NEW_CATEGORIES.contains(s))
                .collect(Collectors.toList());

        assertTrue(orphans.isEmpty(), () ->
                "这些样本既没有母版、也没登记成新类别，等于没人比它：" + orphans);
    }
}
