## GoldenMasterSupport.java

```java
package com.example.freight.golden;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.stream.Stream;

final class GoldenMasterSupport {

    /**
     * 回放时必须抹掉的易变字段，要和录制时的 scrubber 保持同一份清单，
     * 否则每次跑都会因为 traceId / calcTime 变化而红灯。新增易变字段往这里加。
     */
    static final Set<String> SCRUBBED_FIELDS = Set.of("traceId", "calcTime");

    static final String REQUEST_SUFFIX = ".request.json";
    static final String APPROVED_SUFFIX = ".approved.json";
    static final String RECEIVED_SUFFIX = ".received.json";

    static final ObjectMapper MAPPER = new ObjectMapper();

    private GoldenMasterSupport() {
    }

    /** 从工作目录逐级向上找 samples/freight，兼容单模块和多模块（surefire 的 user.dir 是模块目录）。 */
    static Path samplesDir() {
        Path dir = Paths.get(System.getProperty("user.dir")).toAbsolutePath();
        for (int i = 0; i < 5 && dir != null; i++, dir = dir.getParent()) {
            Path candidate = dir.resolve("samples").resolve("freight");
            if (Files.isDirectory(candidate)) {
                return candidate;
            }
        }
        throw new IllegalStateException(
                "找不到 samples/freight，起点 user.dir=" + System.getProperty("user.dir"));
    }

    static List<Path> requestFiles() {
        try (Stream<Path> s = Files.list(samplesDir())) {
            return s.filter(p -> p.getFileName().toString().endsWith(REQUEST_SUFFIX))
                    .sorted()
                    .collect(java.util.stream.Collectors.toList());
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    static String caseName(Path file, String suffix) {
        String n = file.getFileName().toString();
        return n.substring(0, n.length() - suffix.length());
    }

    static Path approvedFile(Path requestFile) {
        return requestFile.resolveSibling(caseName(requestFile, REQUEST_SUFFIX) + APPROVED_SUFFIX);
    }

    static Path receivedFile(Path requestFile) {
        return requestFile.resolveSibling(caseName(requestFile, REQUEST_SUFFIX) + RECEIVED_SUFFIX);
    }

    static JsonNode read(Path p) {
        try {
            return MAPPER.readTree(Files.readAllBytes(p));
        } catch (IOException e) {
            throw new UncheckedIOException("读取样本失败: " + p, e);
        }
    }

    /** 写出 received：内容就是人工核对后可以直接改名成 approved 的形态。 */
    static void writeReceived(Path requestFile, JsonNode output) {
        Path target = receivedFile(requestFile);
        try {
            Files.write(target, (pretty(output) + System.lineSeparator())
                    .getBytes(StandardCharsets.UTF_8));
        } catch (IOException e) {
            throw new UncheckedIOException("写 received 失败: " + target, e);
        }
    }

    static void deleteStaleReceived(Path requestFile) {
        try {
            Files.deleteIfExists(receivedFile(requestFile));
        } catch (IOException ignored) {
            // 清理陈旧 received 失败不影响测试结论
        }
    }

    /** 去掉易变字段 + 对象键排序；保留数字的原始写法，便于人眼 diff 和直接提升为 approved。 */
    static JsonNode scrubAndSort(JsonNode node) {
        if (node.isObject()) {
            List<String> names = new ArrayList<>();
            node.fieldNames().forEachRemaining(names::add);
            Collections.sort(names);
            ObjectNode out = MAPPER.createObjectNode();
            for (String name : names) {
                if (SCRUBBED_FIELDS.contains(name)) {
                    continue;
                }
                out.set(name, scrubAndSort(node.get(name)));
            }
            return out;
        }
        if (node.isArray()) {
            ArrayNode out = MAPPER.createArrayNode();
            node.forEach(e -> out.add(scrubAndSort(e)));
            return out;
        }
        return node.deepCopy();
    }

    /**
     * 比较用形态：在 scrubAndSort 之上再把数字归一。
     * 不归一的话 approved 里的 18(IntNode) 和实际的 18.0(DoubleNode) 会被判不等。
     */
    static JsonNode comparable(JsonNode node) {
        return normalizeNumbers(scrubAndSort(node));
    }

    private static JsonNode normalizeNumbers(JsonNode node) {
        if (node.isObject()) {
            ObjectNode out = MAPPER.createObjectNode();
            node.fields().forEachRemaining(e -> out.set(e.getKey(), normalizeNumbers(e.getValue())));
            return out;
        }
        if (node.isArray()) {
            ArrayNode out = MAPPER.createArrayNode();
            node.forEach(e -> out.add(normalizeNumbers(e)));
            return out;
        }
        if (node.isNumber()) {
            BigDecimal v = node.decimalValue();
            return MAPPER.getNodeFactory()
                    .numberNode(v.signum() == 0 ? BigDecimal.ZERO : v.stripTrailingZeros());
        }
        return node.deepCopy();
    }

    static String pretty(JsonNode node) {
        try {
            return MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(node);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
```

