package com.example.freight.golden;

import com.example.freight.FreightCalc;   // ← 换成实际包名
import com.example.freight.FreightReq;    // ← 换成 calc(req) 实参的实际类型
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

import static com.example.freight.golden.GoldenMasterSupport.*;
import static org.junit.jupiter.api.Assertions.*;

@DisplayName("运费回放比对（golden master）")
class FreightGoldenMasterTest {

    static Stream<org.junit.jupiter.params.provider.Arguments> cases() {
        return requestFiles().stream()
                .map(p -> org.junit.jupiter.params.provider.Arguments.of(
                        caseName(p, REQUEST_SUFFIX), p));
    }

    @ParameterizedTest(name = "{0}")
    @MethodSource("cases")
    @DisplayName("回放结果与已批准输出一致")
    void replayMatchesApproved(String name, Path requestFile) throws Exception {
        FreightReq req = MAPPER.treeToValue(read(requestFile), FreightReq.class);

        JsonNode actualOut = scrubAndSort(MAPPER.valueToTree(FreightCalc.calc(req)));
        Path approved = approvedFile(requestFile);

        if (!Files.exists(approved)) {
            writeReceived(requestFile, actualOut);
            fail("样本 [" + name + "] 没有 approved 基线。已写出 "
                    + receivedFile(requestFile).getFileName()
                    + "，请人工核对是否符合需求，确认后改名为 "
                    + name + APPROVED_SUFFIX + " 并提交。"
                    + "注意：新类别的基线应来自需求，不能因为跑出来就直接批准。");
        }

        JsonNode expectedOut = scrubAndSort(read(approved));
        if (comparable(expectedOut).equals(comparable(actualOut))) {
            deleteStaleReceived(requestFile);
            return;
        }

        writeReceived(requestFile, actualOut);
        String hint = "样本 [" + name + "] 回放结果与基线不符。差异文件见 "
                + receivedFile(requestFile).getFileName()
                + "；确属预期变更时才把它改名为 approved。";
        assertEquals(pretty(expectedOut), pretty(actualOut), hint);
        fail(hint + "（两者文本相同，差异在数值精度）");
    }

    @Test
    @DisplayName("守卫：样本集不能为空")
    void sampleSetIsNotEmpty() {
        assertFalse(requestFiles().isEmpty(),
                "在 " + samplesDir() + " 下没扫到任何 " + REQUEST_SUFFIX
                        + "。样本丢失会让回放测试全绿却什么都没验。");
    }

    @Test
    @DisplayName("守卫：不存在没有 request 的孤儿 approved")
    void noOrphanApprovedFiles() throws IOException {
        List<String> requestCases = requestFiles().stream()
                .map(p -> caseName(p, REQUEST_SUFFIX))
                .collect(Collectors.toList());

        try (Stream<Path> s = Files.list(samplesDir())) {
            List<String> orphans = s
                    .filter(p -> p.getFileName().toString().endsWith(APPROVED_SUFFIX))
                    .map(p -> caseName(p, APPROVED_SUFFIX))
                    .filter(n -> !requestCases.contains(n))
                    .sorted()
                    .collect(Collectors.toList());
            assertTrue(orphans.isEmpty(), "这些 approved 文件找不到对应的 request：" + orphans);
        }
    }
}
