```java
package com.example.freight;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.DecimalNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.fail;

/**
 * 运费计算的回放比对(golden master)。
 *
 * 纪律:
 * 1. *.approved.json 是改动前录的老行为。测试红了先怀疑代码,不许改 approved 让它变绿。
 * 2. 没有 approved 的样本 = 还没人批准过的新类别,测试必然失败并写出 *.received.json,
 *    由人对照需求审核后改名转正,不由程序自己生成基线。
 */
class FreightGoldenMasterTest {

    /** 指向源码树而不是 target/test-classes:received 要落在人能看见、能 diff、能改名的地方。 */
    private static final Path SAMPLES = Paths.get("src/test/resources/samples/freight");

    private static final ObjectMapper MAPPER = new ObjectMapper();

    /** 录制时规整掉的非确定字段,回放侧必须按同一份清单再规整一次。 */
    private static final Set<String> VOLATILE_FIELDS = Set.of("traceId", "calcTime");

    static List<String> samples() throws IOException {
        try (Stream<Path> files = Files.list(SAMPLES)) {
            return files.map(p -> p.getFileName().toString())
                    .filter(n -> n.endsWith(".request.json"))
                    .map(n -> n.substring(0, n.length() - ".request.json".length()))
                    .sorted()
                    .collect(Collectors.toList());
        }
    }

    @ParameterizedTest(name = "{0}")
    @MethodSource("samples")
    void 回放结果与批准基线一致(String sample) throws Exception {
        JsonNode actual = canonicalize(replay(sample));
        Path approved = SAMPLES.resolve(sample + ".approved.json");
        Path received = SAMPLES.resolve(sample + ".received.json");

        if (!Files.exists(approved)) {
            write(received, actual);
            fail("样本 [" + sample + "] 还没有批准基线(新类别)。\n"
                    + "已写出实际结果: " + received + "\n"
                    + "请对照需求人工核对,确认无误后改名为 " + approved.getFileName()
                    + " 再重跑;不要在没核对的情况下直接改名。");
        }

        JsonNode expected = canonicalize(MAPPER.readTree(approved.toFile()));
        if (!expected.equals(actual)) {
            write(received, actual);
            fail("样本 [" + sample + "] 与批准基线不一致。\n"
                    + "approved: " + approved + "\n"
                    + "received: " + received + "\n"
                    + "expected = " + expected + "\n"
                    + "actual   = " + actual + "\n"
                    + "若这是本次改动的预期变化,先确认它确实该变,再更新 approved。");
        }
        Files.deleteIfExists(received);   // 变绿后清掉残留,免得下次看到过期的 received
    }

    /**
     * 新类别的基线不来自程序输出,来自需求翻译里的例子:
     * 模板 1032(配了偏远省份表)+ 新疆 + 3.2kg + vip → 26。
     * 这条独立于上面的回放比对,即使 approved 尚未转正也应当是绿的。
     */
    @Test
    void 偏远省份走新路径_总额符合需求例子() throws Exception {
        JsonNode actual = canonicalize(replay("首重续重-新疆-vip"));
        assertEquals(new BigDecimal("26"), actual.get("fee").decimalValue(),
                "需求例子: 模板1032 + 新疆 + 3.2kg + vip → 26");
    }

    // --- 回放与规整 ---------------------------------------------------------

    private static JsonNode replay(String sample) throws IOException {
        Path request = SAMPLES.resolve(sample + ".request.json");
        // 按实际签名调整:这里假设 calc 收 FreightRequest,返回可被 Jackson 序列化的结果对象。
        FreightRequest req = MAPPER.readValue(request.toFile(), FreightRequest.class);
        return MAPPER.valueToTree(FreightCalc.calc(req));
    }

    /**
     * 规整(scrubbing):
     * - 删掉非确定字段,否则回放永远对不上;
     * - 数值统一成 plain BigDecimal,免得 18 和 18.0 被判不等;
     * - 对象字段名由 JsonNode.equals 按 key 比较,与书写顺序无关;数组保持顺序敏感,
     *   因为 items 的先后本身就是行为的一部分。
     */
    private static JsonNode canonicalize(JsonNode node) {
        if (node.isObject()) {
            ObjectNode obj = (ObjectNode) node;
            obj.remove(VOLATILE_FIELDS);
            obj.fieldNames().forEachRemaining(name -> {});   // 占位:见下一行的安全改写
            for (String name : List.copyOf(iterate(obj.fieldNames()))) {
                obj.set(name, canonicalize(obj.get(name)));
            }
        } else if (node.isArray()) {
            ArrayNode arr = (ArrayNode) node;
            for (int i = 0; i < arr.size(); i++) {
                arr.set(i, canonicalize(arr.get(i)));
            }
        } else if (node.isNumber()) {
            return DecimalNode.valueOf(
                    new BigDecimal(node.decimalValue().stripTrailingZeros().toPlainString()));
        }
        return node;
    }

    private static List<String> iterate(java.util.Iterator<String> it) {
        List<String> out = new java.util.ArrayList<>();
        it.forEachRemaining(out::add);
        return out;
    }

    private static void write(Path target, JsonNode content) throws IOException {
        Files.createDirectories(target.getParent());
        Files.writeString(target,
                MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(content),
                StandardCharsets.UTF_8);
    }
}
